@startuml

class Library {
}

class User {
  + securityDeposit : float
}

class BorrowableItem {
  + libraryCode : int
  + location : string
}

class Book extends BorrowableItem {
  + publisher : string
}

class MagazineIssue extends BorrowableItem {
  + publicationDate : date
  + publisher : string
}

class MusicCD extends BorrowableItem {
  + publisher : string
  + artist : string
}

class Film extends BorrowableItem {
  + duration : time
  + publisher : string
}

class VHSFilm extends Film {}

class DVDFilm extends Film {}

class Author {}

class Actor {}

class ItemTransferRequest {}

Library "1" -- "*" User : has
Library "1" -- "*" BorrowableItem : has
Library "0..1" -- "*" ItemTransferRequest : destination
Library "0..1" -- "*" ItemTransferRequest : source

User "0..1" -- "0..3" BorrowableItem : borrows

Book "*" -- "1..*" Author : has
Film "*" -- "1..*" Actor : has

@enduml

